use vstd::prelude::*;

verus! {

fn swap_first_and_last(a: &Vec<i32>) -> (result: Vec<i32>)
    ensures
        result.len() == a.len(),
        // If the length is 0 or 1, cloning returns the same sequence
        a@.len() <= 1 ==> result@ == a@,
        // If the length is >= 2, only the first and last elements are swapped
        a@.len() > 1 ==> {
            &&& result@[0] == a@[a@.len() - 1]
            &&& result@[a@.len() - 1] == a@[0]
            &&& (forall|i: int|
                    0 <= i && i < a@.len() && i != 0 && i != a@.len() - 1
                    ==> result@[i] == a@[i])
        },
{
    let n = a.len();
    if n <= 1 {
        return a.clone();
    }

    // Facts needed to justify indexing at 0 and n-1
    assert(n >= 2);
    assert(0 < n);
    assert(n - 1 < n);

    let mut result = a.clone();

    // Relate executable length to spec length
    assert(result.len() == n);
    assert(result@.len() == a@.len());

    // Capture pre-state of the sequence for reasoning about swap
    let old = result@;

    result.swap(0, n - 1);

    // Use the swap postcondition on sequences
    assert(result@ == old.update(0, old[n as int - 1]).update(n as int - 1, old[0]));

    result
}

} // verus!